package api

import (
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/veloce-ailab/veloce/internal/model"
	"github.com/veloce-ailab/veloce/internal/service"
	"gorm.io/gorm"
)

// TokenAuthAPI implements the client-secret-free token authorization flow used
// by third-party applications. The authorize endpoint runs behind the normal
// user session, the exchange endpoint is public because the application holds
// no credentials: the state generated by that application is the only thing it
// can redeem.
type TokenAuthAPI struct{}

type tokenAuthAuthorizeInput struct {
	State       string `json:"state"`
	RedirectURI string `json:"redirect_uri"`
	APIKeyID    uint   `json:"api_key_id"`
}

// Authorize approves a pending request and returns the URL the browser should
// be sent back to. The URL carries the application's own state value and never
// the token itself.
func (api *TokenAuthAPI) Authorize(c *gin.Context) {
	user, ok := currentUser(c)
	if !ok {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "Unauthorized"})
		return
	}

	var input tokenAuthAuthorizeInput
	if err := c.ShouldBindJSON(&input); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	state := strings.TrimSpace(input.State)
	if err := service.ValidateTokenAuthState(state); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	redirectURI, err := service.NormalizeTokenAuthRedirectURI(input.RedirectURI)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	var apiKey model.APIKey
	err = model.DB.Where("id = ? AND user_id = ?", input.APIKeyID, user.ID).First(&apiKey).Error
	if errors.Is(err, gorm.ErrRecordNotFound) {
		c.JSON(http.StatusNotFound, gin.H{"error": "API key not found"})
		return
	}
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to load API key"})
		return
	}
	if grantErr := usableTokenAuthAPIKey(apiKey); grantErr != "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": grantErr})
		return
	}

	if err := service.CreateTokenAuthGrant(state, user.ID, apiKey.ID, apiKey.APIKey, redirectURI); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	redirectURL, err := service.TokenAuthCallbackURL(redirectURI, map[string]string{"state": state})
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	userID := user.ID
	service.RecordAuditLog(service.AuditLogInput{
		LogType:    service.AuditLogTypeAPI,
		Action:     "token_authorize_success",
		Resource:   "token_authorize",
		UserID:     &userID,
		APIKeyID:   &apiKey.ID,
		Method:     c.Request.Method,
		Path:       c.Request.URL.Path,
		StatusCode: http.StatusOK,
		IPAddress:  c.ClientIP(),
		UserAgent:  c.Request.UserAgent(),
		Metadata:   redirectURI,
	})

	c.JSON(http.StatusOK, gin.H{
		"redirect_url": redirectURL,
		"expires_in":   int(service.TokenAuthGrantTTL.Seconds()),
	})
}

// Exchange trades the application's state for the approved token. Grants are
// single-use and short-lived; a second call with the same state fails.
func (api *TokenAuthAPI) Exchange(c *gin.Context) {
	var input struct {
		State string `json:"state"`
	}
	if err := c.ShouldBindJSON(&input); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	grant, err := service.ConsumeTokenAuthGrant(strings.TrimSpace(input.State))
	if err != nil {
		service.RecordAuditLog(service.AuditLogInput{
			LogType:    service.AuditLogTypeAPI,
			Action:     "token_exchange_failed",
			Resource:   "token_exchange",
			Method:     c.Request.Method,
			Path:       c.Request.URL.Path,
			StatusCode: http.StatusBadRequest,
			IPAddress:  c.ClientIP(),
			UserAgent:  c.Request.UserAgent(),
			Message:    err.Error(),
		})
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// The key may have been disabled, expired or deleted between approval and
	// redemption, so re-check instead of trusting the grant snapshot.
	var apiKey model.APIKey
	if err := model.DB.Where("id = ? AND user_id = ?", grant.APIKeyID, grant.UserID).First(&apiKey).Error; err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "API key not found"})
		return
	}
	if grantErr := usableTokenAuthAPIKey(apiKey); grantErr != "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": grantErr})
		return
	}

	userID := grant.UserID
	service.RecordAuditLog(service.AuditLogInput{
		LogType:    service.AuditLogTypeAPI,
		Action:     "token_exchange_success",
		Resource:   "token_exchange",
		UserID:     &userID,
		APIKeyID:   &apiKey.ID,
		Method:     c.Request.Method,
		Path:       c.Request.URL.Path,
		StatusCode: http.StatusOK,
		IPAddress:  c.ClientIP(),
		UserAgent:  c.Request.UserAgent(),
	})

	c.JSON(http.StatusOK, gin.H{
		"token":        apiKey.APIKey,
		"token_id":     apiKey.ID,
		"name":         apiKey.Name,
		"key_prefix":   apiKey.KeyPrefix,
		"expires_at":   apiKey.ExpiresAt,
		"api_base_url": tokenAuthRequestOrigin(c) + "/v1",
	})
}

// usableTokenAuthAPIKey reports why a key cannot be handed to a third-party
// application, or an empty string when it can.
func usableTokenAuthAPIKey(apiKey model.APIKey) string {
	if !apiKey.Enabled {
		return "API key is disabled"
	}
	if apiKey.ExpiresAt != nil && !apiKey.ExpiresAt.After(time.Now()) {
		return "API key has expired"
	}
	if strings.TrimSpace(apiKey.APIKey) == "" {
		return "API key cannot be exported"
	}
	return ""
}

func tokenAuthRequestOrigin(c *gin.Context) string {
	host := strings.TrimSpace(c.Request.Host)
	if forwardedHost := strings.TrimSpace(c.GetHeader("X-Forwarded-Host")); forwardedHost != "" {
		host = forwardedHost
	}
	scheme := "http"
	if c.Request.TLS != nil {
		scheme = "https"
	}
	if forwardedProto := strings.TrimSpace(c.GetHeader("X-Forwarded-Proto")); forwardedProto == "http" || forwardedProto == "https" {
		scheme = forwardedProto
	}
	if host == "" {
		return ""
	}
	return scheme + "://" + host
}
